// Actual vendor uniform batch + UBATCH_INDEX + SetValues second-stage baseline.
#pragma once
inline void native_uniform_selected(){
 const char*path=std::getenv("REWRITE_INPUT");std::ifstream cfg(std::string(path)+"/config.txt");std::string kind;int count;cfg>>kind>>count;if(kind!="uniform_batch"||count!=2)throw std::runtime_error("uniform profile");
 int n,nnz,nrhs,ldb,ldx,base,typ,reorder;cfg>>n>>nnz>>nrhs>>ldb>>ldx>>base>>typ>>reorder;
 auto rows=rewrite::read<int>("b0_rows",n+1),columns=rewrite::read<int>("b0_columns",nnz);auto v0=rewrite::read<double>("b0_values",nnz),v1=rewrite::read<double>("b1_values",nnz),b0=rewrite::read<double>("b0_B",ldb*nrhs),b1=rewrite::read<double>("b1_B",ldb*nrhs),x0=rewrite::read<double>("b0_X",ldx*nrhs),x1=rewrite::read<double>("b1_X",ldx*nrhs);v0.insert(v0.end(),v1.begin(),v1.end());b0.insert(b0.end(),b1.begin(),b1.end());x0.insert(x0.end(),x1.begin(),x1.end());
 rewrite::Buffer<int>dr(rows),dc(columns);rewrite::Buffer<double>dv(v0),db(b0),dx(x0);cudssHandle_t h;cudssConfig_t conf;cudssData_t data;cudssMatrix_t a,b,x;RW_CHECK(cudssCreate(&h));RW_CHECK(cudssConfigCreate(&conf));RW_CHECK(cudssDataCreate(h,&data));RW_CHECK(cudssMatrixCreateCsr(&a,n,n,nnz,dr.p,nullptr,dc.p,dv.p,CUDA_R_32I,CUDA_R_32I,CUDA_R_64F,CUDSS_MTYPE_SPD,CUDSS_MVIEW_UPPER,base?CUDSS_BASE_ONE:CUDSS_BASE_ZERO));RW_CHECK(cudssMatrixCreateDn(&b,n,nrhs,ldb,db.p,CUDA_R_64F,CUDSS_LAYOUT_COL_MAJOR));RW_CHECK(cudssMatrixCreateDn(&x,n,nrhs,ldx,dx.p,CUDA_R_64F,CUDSS_LAYOUT_COL_MAJOR));RW_CHECK(cudssConfigSet(conf,CUDSS_CONFIG_UBATCH_SIZE,&count,sizeof(count)));RW_CHECK(cudssExecute(h,CUDSS_PHASE_ANALYSIS,conf,data,a,x,b));RW_CHECK(cudssExecute(h,CUDSS_PHASE_FACTORIZATION,conf,data,a,x,b));rewrite::sync();int first=0;size_t bytes=0;RW_CHECK(cudssDataGet(h,data,CUDSS_DATA_INFO,&first,sizeof(first),&bytes));if(first)throw std::runtime_error("uniform initial factor info");RW_CHECK(cudssExecute(h,CUDSS_PHASE_SOLVE,conf,data,a,x,b));rewrite::sync();auto initial=dx.get();rewrite::emit("uniform_initial_X",initial);rewrite::emit("uniform_initial_B_after",db.get());rewrite::emit("uniform_initial_values_after",dv.get());
 int index=1;RW_CHECK(cudssConfigSet(conf,CUDSS_CONFIG_UBATCH_INDEX,&index,sizeof(index)));RW_CHECK(cudssMatrixSetValues(a,dv.p+nnz));RW_CHECK(cudssMatrixSetValues(b,db.p+ldb*nrhs));RW_CHECK(cudssExecute(h,CUDSS_PHASE_FACTORIZATION,conf,data,a,x,b));rewrite::sync();int selected=0;RW_CHECK(cudssDataGet(h,data,CUDSS_DATA_INFO,&selected,sizeof(selected),&bytes));if(selected)throw std::runtime_error("selected factor info");RW_CHECK(cudssExecute(h,CUDSS_PHASE_SOLVE,conf,data,a,x,b));rewrite::sync();auto final=dx.get();rewrite::emit("uniform_selected_B_after",db.get());rewrite::emit("uniform_selected_values_after",dv.get());rewrite::emit("uniform_final_X",final);rewrite::emit("uniform_selected_solution",std::vector<double>(final.begin(),final.begin()+ldx*nrhs));rewrite::emit("uniform_selection",std::vector<int>{1,0,2});rewrite::emit("uniform_native_info",std::vector<int>{first,selected});RW_CHECK(cudssMatrixDestroy(a));RW_CHECK(cudssMatrixDestroy(b));RW_CHECK(cudssMatrixDestroy(x));RW_CHECK(cudssDataDestroy(h,data));RW_CHECK(cudssConfigDestroy(conf));RW_CHECK(cudssDestroy(h));
}
